reference_solution:
def sum_to(n):
    total = 0
    for i in range(1, n + 1):
        total = total + i
    return total

def count_evens(nums):
    count = 0
    for n in nums:
        if n % 2 == 0:
            count = count + 1
    return count

def grade(score):
    if score >= 90:
        return "A"
    elif score >= 80:
        return "B"
    else:
        return "C"

def add_lists(a, b):
    result = []
    for i in range(len(a)):
        result.append(a[i] + b[i])
    return result

def count_char(s, ch):
    count = 0
    for c in s:
        if c == ch:
            count = count + 1
    return count

def add_item(lst, x):
    lst.append(x)
    return lst

def max_of(nums):
    best = nums[0]
    for n in nums:
        if n > best:
            best = n
    return best

def describe_temp(t):
    if t > 25:
        return "hot"
    elif t > 15:
        return "warm"
    return "cold"

def countdown(n):
    result = []
    for i in range(n, 0, -1):
        result.append(i)
    return result

def double_all(nums):
    result = []
    for n in nums:
        result.append(n * 2)
    return result

def total_length(words):
    total = 0
    for w in words:
        total = total + len(w)
    return total
